<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
$user=require_user();
$serviceId=(int)($_GET['id']??0);
$q=db()->prepare('SELECT s.*,p.name product_name,p.linode_type,p.linode_region,p.linode_image FROM services s LEFT JOIN store_products p ON p.id=s.product_id WHERE s.id=? AND s.user_id=? LIMIT 1');
$q->execute([$serviceId,(int)$user['id']]);
$service=$q->fetch();
if(!$service||linode_service_provider($service)!=='linode'){http_response_code(404);die('VPS service not found.');}
header('Cache-Control: no-store, private');

$credentials=linode_service_credentials($service);
$serviceConfig=json_decode((string)($service['config_json']??''),true)?:[];
$serviceImage=(string)($serviceConfig['linode_image_label']??$serviceConfig['linode_image']??$service['linode_image']??'—');
$instance=[];$apiError='';
if(!empty($service['linode_instance_id'])){try{$instance=linode_api('/linode/instances/'.(int)$service['linode_instance_id']);}catch(Throwable $error){$apiError=$error->getMessage();}}
$status=(string)($instance['status']??$service['status']??'pending');
$specs=(array)($instance['specs']??[]);$alerts=(array)($instance['alerts']??[]);$backupStatus=(array)($instance['backups']??[]);
$tags=(array)($instance['tags']??[]);$ipv4=(string)(($instance['ipv4'][0]??'')?:$credentials['ipv4']);$ipv6=(string)(($instance['ipv6']??'')?:$credentials['ipv6']);
$canPower=!empty($service['linode_instance_id'])&&in_array((string)$service['status'],['active','provisioning'],true);
$maintenancePolicy=(string)($instance['maintenance_policy']??'—');
$created=!empty($instance['created'])?date('d M Y, H:i',strtotime((string)$instance['created'])):'—';
?>
