<script>
const VPS_ID=<?=json_encode($serviceId)?>,CSRF=<?=json_encode(csrf())?>,CAN_POWER=<?=json_encode($canPower)?>;
const loaded=new Set();
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const nice=value=>String(value||'—').replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase());
const dateTime=value=>value?new Date(value).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'—';
const toast=(message,error=false)=>{const el=document.querySelector('[data-toast]');el.textContent=message;el.className='cloud-toast is-visible'+(error?' is-error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('is-visible'),3200)};
const fact=(label,value)=>'<div class="cloud-fact"><span>'+esc(label)+'</span><b>'+esc(value)+'</b></div>';
function empty(icon,title,text){return '<div class="cloud-empty"><div><i class="fas '+icon+'"></i><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p></div></div>'}
function flattenNetwork(network){const rows=[];const ipv4=network?.ipv4||{};Object.entries(ipv4).forEach(([group,items])=>(items||[]).forEach(ip=>rows.push([ip.address,'IPv4 · '+group,ip.gateway||'—','/'+(ip.prefix??'—'),ip.rdns||'—',ip.public?'Public':'Private'])));const ipv6=network?.ipv6||{};Object.entries(ipv6).forEach(([group,value])=>{const items=Array.isArray(value)?value:(value?[value]:[]);items.forEach(ip=>rows.push([ip.address,'IPv6 · '+group,ip.gateway||'—','/'+(ip.prefix??'—'),ip.rdns||'—',ip.public?'Public':'Private']))});return rows}
function table(headers,rows){return '<div class="cloud-table-wrap"><table class="cloud-table"><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((cell,index)=>'<td>'+(index===0?'<code>'+esc(cell)+'</code>':esc(cell))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function drawChart(canvas,points,color){const ctx=canvas.getContext('2d'),ratio=devicePixelRatio||1,width=canvas.clientWidth||500,height=180;canvas.width=width*ratio;canvas.height=height*ratio;ctx.scale(ratio,ratio);ctx.clearRect(0,0,width,height);ctx.strokeStyle='rgba(255,255,255,.08)';ctx.lineWidth=1;for(let i=0;i<5;i++){const y=15+i*(height-30)/4;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke()}if(!points.length)return;const values=points.map(p=>Number(p[1]||0)),max=Math.max(1,...values);ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();points.forEach((point,index)=>{const x=points.length===1?width/2:index*(width/(points.length-1));const y=height-16-(Number(point[1]||0)/max)*(height-32);index?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#8190a5';ctx.font='10px sans-serif';ctx.fillText('Max '+max.toFixed(1),8,12)}
function renderMetrics(body,result){if(!result.available){body.innerHTML=empty('fa-hourglass-half','Stats are not available yet',result.message||'CPU, network and disk statistics will appear shortly.');return}const data=result.stats?.data||{};const series=[['CPU usage',data.cpu||[],'#63aaff'],['Disk I/O',(data.io||[]).map(p=>[p[0],Number(p[1]||0)+Number(p[2]||0)]),'#a879ff'],['IPv4 traffic',(data.netv4||[]).map(p=>[p[0],Number(p[1]||0)+Number(p[2]||0)]),'#3ed69b'],['IPv6 traffic',(data.netv6||[]).map(p=>[p[0],Number(p[1]||0)+Number(p[2]||0)]),'#f2ad55']];body.innerHTML='<div class="metric-grid">'+series.map((s,i)=>'<div class="metric-card"><h3>'+esc(s[0])+'</h3><canvas data-chart="'+i+'"></canvas></div>').join('')+'</div>';series.forEach((seriesItem,index)=>drawChart(body.querySelector('[data-chart="'+index+'"]'),seriesItem[1],seriesItem[2]))}
function renderSection(section,body,result){if(section==='metrics')return renderMetrics(body,result);if(section==='network'){const rows=flattenNetwork(result.network);body.innerHTML=rows.length?table(['Address','Type','Gateway','Prefix','Reverse DNS','Access'],rows):empty('fa-network-wired','No addresses','No network addresses were returned.');return}if(section==='storage'){const items=[...(result.disks||[]).map(item=>({...item,kind:'Disk'})),...(result.volumes||[]).map(item=>({...item,kind:'Volume'}))];body.innerHTML=items.length?'<div class="cloud-item-grid">'+items.map(item=>'<article class="cloud-item"><h3>'+esc(item.label||item.kind)+'</h3><div class="cloud-facts">'+fact('Type',item.kind)+fact('Status',nice(item.status))+fact('Size',Number(item.size||0).toLocaleString()+' MB')+fact('Filesystem',item.filesystem||'—')+fact('Encryption',nice(item.disk_encryption||'—'))+fact('Created',dateTime(item.created))+'</div></article>').join('')+'</div>':empty('fa-hdd','No storage','No disks or volumes were returned.');return}if(section==='configurations'){const configs=result.configurations||[];body.innerHTML=configs.length?'<div class="cloud-item-grid">'+configs.map(config=>{const devices=Object.entries(config.devices||{}).filter(([,device])=>device).map(([slot,device])=>slot.toUpperCase()+': '+(device.disk_id?'Disk #'+device.disk_id:'Volume #'+device.volume_id)).join(' · ');return '<article class="cloud-item"><h3>'+esc(config.label)+'</h3><div class="cloud-facts">'+fact('Kernel',config.kernel)+fact('Root device',config.root_device)+fact('Virtualization',config.virt_mode)+fact('Run level',config.run_level)+fact('Devices',devices||'None')+fact('Updated',dateTime(config.updated))+'</div></article>'}).join('')+'</div>':empty('fa-sliders-h','No configurations','No configuration profiles were returned.');return}if(section==='backups'){const status=result.status||{},automatic=result.backups?.automatic||[],snapshot=[result.backups?.snapshot?.current,result.backups?.snapshot?.in_progress].filter(Boolean),items=[...automatic,...snapshot];body.innerHTML='<div class="alert-grid" style="margin-bottom:16px"><div class="alert-card"><span>Backup service</span><b>'+(status.enabled?'Enabled':'Disabled')+'</b></div><div class="alert-card"><span>Last successful</span><b style="font-size:13px">'+esc(dateTime(status.last_successful))+'</b></div></div>'+(items.length?'<div class="cloud-item-grid">'+items.map(item=>'<article class="cloud-item"><h3>'+esc(item.label||nice(item.type))+'</h3><div class="cloud-facts">'+fact('Status',nice(item.status))+fact('Type',nice(item.type))+fact('Created',dateTime(item.created))+fact('Finished',dateTime(item.finished))+'</div></article>').join('')+'</div>':empty('fa-archive','No backups yet','The backup service is scheduling its first backup.'));return}const events=result.events||[];body.innerHTML=events.length?events.map(event=>'<div class="cloud-event '+(event.status==='failed'?'is-failed':'')+'"><i></i><div><b>'+esc(nice(event.action))+'</b><small>'+esc(event.message||('Event #'+event.id+' · '+nice(event.status)))+(event.duration!==null?' · '+esc(event.duration)+' seconds':'')+'</small></div><time>'+esc(dateTime(event.created))+'</time></div>').join(''):empty('fa-history','No activity','No recent activity was returned for this VPS.')}
async function loadSection(section,force=false){if(loaded.has(section)&&!force)return;const body=document.querySelector('[data-panel-body="'+section+'"]');if(!body)return;body.innerHTML='<div class="cloud-loading"><div><i class="fas fa-circle-notch fa-spin"></i><br>Loading '+esc(section)+'…</div></div>';try{const response=await fetch('/api/vps-details.php?id='+VPS_ID+'&section='+encodeURIComponent(section),{headers:{Accept:'application/json'}});const result=await response.json();if(!result.ok)throw new Error(result.error||'VPS data unavailable');renderSection(section,body,result);loaded.add(section)}catch(error){body.innerHTML=empty('fa-exclamation-circle','Could not load '+section,error.message||String(error))}}
function openTab(tab){document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('is-active',button.dataset.tab===tab));document.querySelectorAll('[data-panel]').forEach(panel=>panel.classList.toggle('is-active',panel.dataset.panel===tab));if(!['alerts','settings'].includes(tab))loadSection(tab)}
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>openTab(button.dataset.tab)));
document.querySelectorAll('[data-reload]').forEach(button=>button.addEventListener('click',()=>loadSection(button.dataset.reload,true)));
document.querySelectorAll('[data-copy-value]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copyValue||'');toast('Copied to clipboard.')}catch(error){toast('Could not copy.',true)}}));
document.querySelector('[data-reveal]')?.addEventListener('click',button=>{const secret=document.querySelector('[data-secret]');secret.classList.toggle('is-visible');button.currentTarget.innerHTML=secret.classList.contains('is-visible')?'<i class="far fa-eye-slash"></i>':'<i class="far fa-eye"></i>'});
document.querySelectorAll('[data-power]').forEach(button=>button.addEventListener('click',async()=>{if(!CAN_POWER)return;const buttons=[...document.querySelectorAll('[data-power]')];buttons.forEach(item=>item.disabled=true);try{const response=await fetch('/api/power.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({id:String(VPS_ID),signal:button.dataset.power})});const result=await response.json();if(!result.ok)throw new Error(result.error||'Power action failed');toast(nice(button.dataset.power)+' command sent.');setTimeout(()=>location.reload(),2200)}catch(error){toast(error.message||String(error),true);buttons.forEach(item=>item.disabled=false)}}));
document.querySelector('[data-refresh]')?.addEventListener('click',()=>location.reload());
document.querySelector('[data-settings-form]')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),message=form.querySelector('[data-settings-message]'),data=new FormData(form);button.disabled=true;message.textContent='Saving…';try{const response=await fetch('/api/vps-settings.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({id:VPS_ID,label:data.get('label'),watchdog_enabled:data.get('watchdog_enabled')==='1',alerts:{cpu:Number(data.get('cpu')),network_in:Number(data.get('network_in')),network_out:Number(data.get('network_out')),transfer_quota:Number(data.get('transfer_quota')),io:Number(data.get('io'))}})});const result=await response.json();if(!result.ok)throw new Error(result.error||'Settings could not be saved');message.textContent='Settings saved.';toast('Linode settings updated.')}catch(error){message.textContent='';toast(error.message||String(error),true)}finally{button.disabled=false}});
loadSection('metrics');
</script>
</body>
</html>
